/**
 * @file shell.cuh
 * @brief Cartesian shell bookkeeping and Gaussian normalization constants.
 *
 * Cartesian component order (identical to libcint / PySCF with cart=True):
 *
 *   l = 0 : 1s
 *   l = 1 : x, y, z
 *   l = 2 : xx, xy, xz, yy, yz, zz
 *
 * which is generated by iterating lx from l down to 0 and, for each lx,
 * ly from l-lx down to 0 and lz = l-lx-ly.  This ordering is what the
 * PySCF validation harness in scripts/validate_vs_pyscf.py assumes.
 *
 * Normalization.  A primitive Cartesian Gaussian is written as
 *
 *   g_p(r) = N(l, alpha_p) (x-Ax)^lx (y-Ay)^ly (z-Az)^lz exp(-alpha_p |r-A|^2)
 *
 * with the shell (not per-component) normalization
 *
 *   N(l, alpha) = (2 alpha / pi)^(3/4) (4 alpha)^(l/2) / sqrt((2l-1)!!).
 *
 * The contraction coefficients exported from PySCF are multiplied by N(l,alpha)
 * and then scaled so that every contracted Cartesian component has unit
 * self-overlap.  PySCF itself does not unit-normalize Cartesian d components,
 * so the validation harness applies the exact diagonal similarity transform
 * D = diag(sqrt(diag(S_pyscf))) before comparing.  See docs/NUMERICS.md.
 *
 * The file is compiled as host code and as CUDA device code, so it uses only
 * plain arithmetic and the global math overloads (sqrt, exp, erf).
 */
#ifndef CUEST_SHELL_CUH
#define CUEST_SHELL_CUH

#include <math.h>

#include "../cuest_macros.h"

/** @brief Pi as a compile-time constant usable in host and device code. */
constexpr double CUEST_PI = 3.14159265358979323846264338327950288;

/** @brief Number of Cartesian components of angular momentum @p l. */
CUEST_HD inline int cuest_num_cart(int l) { return (l + 1) * (l + 2) / 2; }

/**
 * @brief Double factorial n!! with (-1)!! = 0!! = 1.
 */
CUEST_HD inline double cuest_double_factorial(int n) {
  double r = 1.0;
  for (int k = n; k > 0; k -= 2) r *= static_cast<double>(k);
  return r;
}

/**
 * @brief Map a flat component index to (lx,ly,lz) for angular momentum @p l.
 */
CUEST_HD inline void cuest_cart_component(int l, int idx, int *lx, int *ly, int *lz) {
  int k = 0;
  for (int ix = l; ix >= 0; --ix) {
    for (int iy = l - ix; iy >= 0; --iy) {
      if (k == idx) {
        if (lx) *lx = ix;
        if (ly) *ly = iy;
        if (lz) *lz = l - ix - iy;
        return;
      }
      ++k;
    }
  }
}

/**
 * @brief Normalization constant of a primitive Cartesian Gaussian shell.
 *
 * Component independent: it normalizes the (l,0,0) component and is applied to
 * every Cartesian component of the shell, matching the PySCF/libcint
 * convention.  Per-component unit normalization is obtained separately by the
 * basis loader.
 */
CUEST_HD inline double cuest_prim_norm(int l, double alpha) {
  double four_a_pow = 1.0; /* (4 alpha)^l, l <= 2 */
  for (int k = 0; k < l; ++k) four_a_pow *= 4.0 * alpha;
  return pow(2.0 * alpha / CUEST_PI, 0.75) *
         sqrt(four_a_pow / cuest_double_factorial(2 * l - 1));
}

/**
 * @brief 1-D Gaussian moment integral I_n(p) = int x^n exp(-p x^2) dx.
 *
 * Returns zero for odd @p n.
 */
CUEST_HD inline double cuest_gauss_moment_1d(int n, double p) {
  if (n & 1) return 0.0;
  double half_pow = 1.0; /* (2p)^(n/2) without std::pow for device safety */
  for (int k = 0; k < n / 2; ++k) half_pow *= 2.0 * p;
  return cuest_double_factorial(n - 1) / half_pow * sqrt(CUEST_PI / p);
}

#endif /* CUEST_SHELL_CUH */
